sys_ui_page.client_script:
function submitDeactivationRequest() {
	console.log('submitDeactivationRequest called');

	// Detect if we're in workspace mode
	isActionFromWorkspace();

	var sys_user = gel(gel('target_user_query').value);
	var display = gel('sys_display.' + gel('target_user_query').value);

	// Check if user is selected
	if (!sys_user || !sys_user.value || sys_user.value == '') {
		alert(getMessage('Please select a user for deactivation'));
		return;
	}

	var reason = gel('deactivation_reason').value;
	if (!reason) {
		alert(getMessage('Please select a deactivation reason'));
		return;
	}

	var deactivate_at = gel('deactivate_at').value;
	if (!deactivate_at) {
		alert(getMessage('Please specify deactivation time'));
		return;
	}

	console.log('Validation passed, proceeding with AJAX call');

	// Disable submit button to prevent double-clicks
	var okButton = gel('ok_button');
	if (okButton) {
		okButton.disabled = true;
		okButton.style.opacity = '0.5';
		okButton.style.cursor = 'not-allowed';
	}

	// Disable cancel button to prevent cancellation during submission
	var cancelButton = gel('cancel_button');
	if (cancelButton) {
		cancelButton.disabled = true;
		cancelButton.style.opacity = '0.5';
		cancelButton.style.cursor = 'not-allowed';
	}

	// Show loading indicator with null check
	var loadingIndicator = gel('loading_indicator');
	var dialogButtons = gel('dialog_buttons');

	if (loadingIndicator) {
		loadingIndicator.style.display = 'table-row';
	} else {
		console.warn('Loading indicator element not found');
	}

	if (dialogButtons) {
		dialogButtons.style.display = 'none';
	} else {
		console.warn('Dialog buttons element not found');
	}

	// Get user details safely
	var userName = '';
	var userEmail = '';
	var targetUserId = '';

	var nameElement = gel('display_name');
	var emailElement = gel('display_email');
	var userIdElement = gel('display_user_id');

	if (nameElement) {
		userName = nameElement.innerHTML || display.value;
	}
	if (emailElement) {
		userEmail = emailElement.innerHTML || '';
	}
	if (userIdElement) {
		targetUserId = userIdElement.innerHTML || '';
	}

	var incidentElement = gel('incident_id');
	var incidentId = incidentElement ? incidentElement.value || '' : '';

	console.log('Parameters:', {
		selectedUserId: sys_user.value,
		userName: userName,
		userEmail: userEmail,
		targetUserId: targetUserId,
		reason: reason,
		incidentId: incidentId
	});

	// Call Script Include via AJAX
	var ga = new GlideAjax('CoreOneDeactivationAjax');
	ga.addParam('sysparm_name', 'createDeactivationRequest');
	ga.addParam('sysparm_selected_user_id', sys_user.value);
	ga.addParam('sysparm_target_user_id', targetUserId);
	ga.addParam('sysparm_user_name', userName);
	ga.addParam('sysparm_user_email', userEmail);
	ga.addParam('sysparm_reason', reason);
	ga.addParam('sysparm_other_reason', gel('other_reason') ? gel('other_reason').value || '' : '');
	ga.addParam('sysparm_deactivate_at', deactivate_at);
	ga.addParam('sysparm_additional_notes', gel('additional_notes') ? gel('additional_notes').value || '' : '');
	ga.addParam('sysparm_incident_id', incidentId);

	console.log('Making AJAX call...');

	ga.getXMLAnswer(function(answer) {
		console.log('AJAX response:', answer);

		// Hide loading indicator safely
		if (loadingIndicator) {
			loadingIndicator.style.display = 'none';
		}
		if (dialogButtons) {
			dialogButtons.style.display = 'table-row';
		}

		// Re-enable buttons in case of error
		if (okButton) {
			okButton.disabled = false;
			okButton.style.opacity = '1';
			okButton.style.cursor = 'pointer';
		}
		if (cancelButton) {
			cancelButton.disabled = false;
			cancelButton.style.opacity = '1';
			cancelButton.style.cursor = 'pointer';
		}

		if (answer && answer.indexOf('success:') === 0) {
			var parts = answer.split(':');
			var ritmNumber = parts[1];

			console.log('Success! RITM created:', ritmNumber);  // Silent logging

			// OLD CODE - doesn't work properly in workspaces
			// if (typeof g_dialog !== 'undefined' && g_dialog) {
			//     g_dialog.destroy();
			// }
			// if (!isActionFromWorkspace()) {
			//     if (typeof g_dialog !== 'undefined' && g_dialog) {
			//         g_dialog.destroy();
			//     }
			// }

			// NEW CODE - uses closeDialog helper for both modes
			closeDialog();

			// OLD REDIRECT CODE - might not work in workspaces
			// if (incidentId && window.parent) {
			//     window.parent.location.href = '/incident.do?sys_id=' + incidentId;
			// }

			// Note: Incident redirect removed to allow dialog to close properly
			// The incident should already have work notes updated by the backend
		} else {
			// Handle error responses
			console.error('AJAX call failed or returned error:', answer);
			var errorMessage = answer || 'Failed to create deactivation request';
			if (errorMessage.indexOf('error:') === 0) {
				errorMessage = errorMessage.substring(6);
			}
			alert(getMessage('Error') + ': ' + errorMessage);
		}
	});
}

/**
 * Custom cancel function with workspace compatibility
 * Closes dialog in both platform and workspace modes
 */
function cancel() {
	console.log('cancel called');

	// OLD CODE - doesn't work in workspaces
	// if (typeof g_dialog !== 'undefined' && g_dialog) {
	//     g_dialog.destroy();
	// }
	// if (!isActionFromWorkspace()) {
	//     GlideDialogWindow.get().destroy();
	// }

	// NEW CODE - uses closeDialog helper for both modes
	closeDialog();
}

function toggleOtherReason() {
    var reason = gel('deactivation_reason');
    var otherGroup = gel('other_reason_group');
    if (reason && otherGroup) {
        if (reason.value === 'other') {
            otherGroup.style.display = 'table-row';
        } else {
            otherGroup.style.display = 'none';
            var otherField = gel('other_reason');
            if (otherField) otherField.value = '';
        }
    }
}

function setCurrentDateTime() {
    var dateField = gel('deactivate_at');
    if (dateField) {
        var now = new Date();
        var year = now.getFullYear();
        var month = (now.getMonth() + 1);
        var day = now.getDate();
        var hours = now.getHours();
        var minutes = now.getMinutes();

        if (month < 10) month = '0' + month;
        if (day < 10) day = '0' + day;
        if (hours < 10) hours = '0' + hours;
        if (minutes < 10) minutes = '0' + minutes;

        var formatted = year + '-' + month + '-' + day + 'T' + hours + ':' + minutes;
        dateField.value = formatted;
    }
}

function populateUserDetails(userSysId) {
    if (userSysId) {
        var ga = new GlideAjax('CoreOneDeactivationAjax');
        ga.addParam('sysparm_name', 'getUserDetails');
        ga.addParam('sysparm_user_id', userSysId);

        ga.getXMLAnswer(function(answer) {
            try {
                var userData = JSON.parse(answer);
                var nameField = gel('display_name');
                var emailField = gel('display_email');
                var userIdField = gel('display_user_id');
                var deptField = gel('display_department');
                var companyField = gel('display_company');
                var deptRow = gel('display_department_row');
                var companyRow = gel('display_company_row');
                var detailsSection = gel('user_details_section');

                if (nameField) nameField.innerHTML = userData.name || '';
                if (emailField) emailField.innerHTML = userData.email || '';
                if (userIdField) userIdField.innerHTML = userData.user_id || '';

                if (userData.department && deptField && deptRow) {
                    deptField.innerHTML = userData.department;
                    deptRow.style.display = 'table-row';
                }

                if (userData.company && companyField && companyRow) {
                    companyField.innerHTML = userData.company;
                    companyRow.style.display = 'table-row';
                }

                if (detailsSection) detailsSection.style.display = 'table-row';
            } catch (e) {
                alert(getMessage('Error retrieving user details') + ': ' + e.message);
            }
        });
    }
}

function onUserSelectionChange() {
    var queryField = gel('target_user_query');
    if (queryField) {
        var sys_user = gel(queryField.value);
        if (sys_user && sys_user.value) {
            populateUserDetails(sys_user.value);

            // Force close the dropdown by blurring the display field
            var displayField = gel('sys_display.' + queryField.value);
            if (displayField) {
                setTimeout(function() {
                    displayField.blur();
                    // Hide any open suggestion dropdowns
                    var suggestions = document.querySelectorAll('.ac_results');
                    for (var i = 0; i < suggestions.length; i++) {
                        suggestions[i].style.display = 'none';
                    }
                }, 100);
            }
        }
    }
}

/**
 * Determine if the action performed was from platform or on workspace
 * Added for workspace compatibility
 */
function isActionFromWorkspace() {
	var fromWorkspace = getParmVal('from_workspace') === "true";

	// Set the hidden input field that determined whether or not the
	// submission was from platform or workspace
	var c = gel('from_workspace');

	if (fromWorkspace)
		c.value = "true";
	else
		c.value = "false";

	return fromWorkspace;
}

/**
 * Helper function to get the parameter values from the URL
 * Added for workspace compatibility
 *
 * @param {string} name of the url parameter to fetch
 */
function getParmVal(name) {
	var url = document.URL.parseQuery();
	if (url[name]) {
		return decodeURI(url[name]);
	}
	return;
}

/**
 * Close the dialog - works in both platform and workspace modes
 */
function closeDialog() {
	console.log('closeDialog called');

	if (isActionFromWorkspace()) {
		console.log('Closing workspace dialog');
		// In workspace mode, use window.close() or post message to parent
		try {
			// Try to close the window/iframe
			if (window.parent && window.parent !== window) {
				// We're in an iframe, try posting a message
				window.parent.postMessage({
					type: 'dialog.close',
					source: 'coreone_deactivate_dialog'
				}, '*');
			}
			// Also try window.close as fallback
			window.close();
		} catch (e) {
			console.error('Error closing workspace dialog:', e);
		}
	} else {
		console.log('Closing platform dialog');
		// Platform view - use traditional methods
		try {
			if (typeof GlideDialogWindow !== 'undefined') {
				GlideDialogWindow.get().destroy();
			} else if (typeof g_dialog !== 'undefined' && g_dialog) {
				g_dialog.destroy();
			}
		} catch (e) {
			console.error('Error closing platform dialog:', e);
		}
	}
}

sys_ui_page.processing_script:
// Set window properties for dialog
try {
    var incidentId = '';
    var incidentNumber = 'Unknown';

    // Try to get incident ID from URL parameters
    if (typeof sysparm_incident_id !== 'undefined') {
        incidentId = sysparm_incident_id;

        // Get incident details for title
        var incident = new GlideRecord('incident');
        if (incident.get(incidentId)) {
            incidentNumber = incident.number.toString();
        }
    }

    // Set dialog properties (this works without RP)
    if (typeof window !== 'undefined' && window.name) {
        document.title = 'CoreOne User Deactivation - ' + incidentNumber;
    }

} catch (e) {
    // Ignore errors in window setup
}
